import{_ as i,E as a,h as l,c as h,b as e,f as c,H as r,a4 as n,w as u}from"./chunks/framework.B_fYP6Of.js";const y=JSON.parse('{"title":"Chunking, source structure and retrieval","description":"See how a document split can separate a rule from its exception. Compare two chunking strategies in an offline lab using source IDs and real questions.","frontmatter":{"title":"Chunking, source structure and retrieval","description":"See how a document split can separate a rule from its exception. Compare two chunking strategies in an offline lab using source IDs and real questions.","teaser":"The right paragraph can lose its meaning at a page break. Two small experiments show which cuts preserve the evidence a reader needs."},"headers":[],"relativePath":"students/chunking.md","filePath":"students/chunking.md"}'),d={name:"students/chunking.md"};function p(g,t,m,b,f,k){const o=a("LabArticleHeader"),s=a("LabScroll");return l(),h("div",null,[t[1]||(t[1]=e("h1",{id:"chunking-where-should-we-cut-a-document",tabindex:"-1"},[c("Chunking: where should we cut a document? "),e("a",{class:"header-anchor",href:"#chunking-where-should-we-cut-a-document","aria-label":'Permalink to "Chunking: where should we cut a document?"'},"​")],-1)),r(o),t[2]||(t[2]=n('<p>A travel handbook says, “Your manager approves reimbursements,” then adds an exception on the next page. An assistant retrieves only the first page. It can quote every word correctly and still send an employee to the wrong person.</p><p><strong>Chunking</strong> divides documents into pieces your search system can return. A useful piece carries enough context to interpret the claim and a source ID and location that let the reader check it. Choose a boundary by trying questions your users will ask. Document structure, model limits and the cost of retrieving extra text all matter. <a href="https://www.pinecone.io/learn/chunking-strategies/" target="_blank" rel="noreferrer">Technical overview of chunking strategies</a></p><p>Start with the <a href="#one-fictional-example">club bulletin</a>, then <a href="#two-experiments-you-can-do-without-an-api-key">try two splits without an API key</a>.</p><h2 id="one-fictional-example" tabindex="-1">One fictional example <a class="header-anchor" href="#one-fictional-example" aria-label="Permalink to &quot;One fictional example&quot;">​</a></h2><p>```text SOURCE: S-events — Harbor Club bulletin, section &quot;Events&quot; [Paragraph 1] The Events Committee organizes monthly workshops. [Paragraph 2] Visitors must sign in at the welcome desk. [Paragraph 3] The date of the next annual meeting has not been announced. ```</p><p><strong>Option A: fixed-size character chunks.</strong> Easy to implement, but a boundary could split “Events Committee organizes” across two chunks. <em>Characters and model tokens are not interchangeable units.</em></p><p><strong>Option B: paragraph/heading chunks.</strong> Keeps each statement together and helps preserve the section title, but a paragraph can be too long or need neighboring context.</p><p><strong>What should the citation say?</strong> Keep the parent source and the location with each piece. The ID <code>S-events-C02</code> directs a reader back to one slice of <code>S-events</code>. It lets them recover the surrounding paragraph and check the meaning.</p><h2 id="choose-a-boundary-deliberately" tabindex="-1">Choose a boundary deliberately <a class="header-anchor" href="#choose-a-boundary-deliberately" aria-label="Permalink to &quot;Choose a boundary deliberately&quot;">​</a></h2>',9)),r(s,{kind:"table",label:"table for Choose a boundary deliberately"},{default:u(()=>[...t[0]||(t[0]=[e("table",{tabindex:"0"},[e("thead",null,[e("tr",null,[e("th",{scope:"col"},"Strategy"),e("th",{scope:"col"},"Why developers use it"),e("th",{scope:"col"},"Common failure")])]),e("tbody",null,[e("tr",null,[e("td",null,"Fixed length"),e("td",null,"Simple, predictable processing limits"),e("td",null,"Breaks sentences, tables, names or claims")]),e("tr",null,[e("td",null,"Sliding window/overlap"),e("td",null,"Carries some context across boundaries"),e("td",null,"Duplicates content, increases cost and may skew rankings")]),e("tr",null,[e("td",null,"Paragraph or heading"),e("td",null,"Respects the author's structure"),e("td",null,"Oversized paragraphs, uneven chunk lengths")]),e("tr",null,[e("td",null,"Recursive splitting"),e("td",null,"Tries larger boundaries then smaller ones"),e("td",null,"Still depends on length limits and separators")]),e("tr",null,[e("td",null,"Semantic splitting"),e("td",null,"Tries to keep related ideas together"),e("td",null,"Requires extra modeling, cost and tuning")]),e("tr",null,[e("td",null,"Parent-child retrieval"),e("td",null,"Search small units, return a larger parent section"),e("td",null,"More complex indexing and source mapping")])])],-1)])]),_:1}),t[3]||(t[3]=n('<p><strong>Start with a paragraph.</strong> Inspect one result where it works and one where a needed name, table header or exception falls outside the boundary. Those observations give you a reason to try a different split.</p><h2 id="the-metadata-that-makes-retrieval-trustworthy" tabindex="-1">The metadata that makes retrieval trustworthy <a class="header-anchor" href="#the-metadata-that-makes-retrieval-trustworthy" aria-label="Permalink to &quot;The metadata that makes retrieval trustworthy&quot;">​</a></h2><p>Each stored chunk should identify:</p><p>```text source_id S-events source_version teaching-fixture-v1 chunk_id S-events-C02 ordinal 2 source_location section: Events / paragraph: 2 text Visitors must sign in at the welcome desk. chunk_method paragraph ```</p><p>This is an illustrative record, not proof that every field exists in our teaching script. If a source changes, decide what to reprocess and how outdated chunks/vectors stop being returned. Stable source identity and source version are more important than pretending generated chunk numbers never change.</p><h2 id="two-experiments-you-can-do-without-an-api-key" tabindex="-1">Two experiments you can do without an API key <a class="header-anchor" href="#two-experiments-you-can-do-without-an-api-key" aria-label="Permalink to &quot;Two experiments you can do without an API key&quot;">​</a></h2><p><strong>Experiment A — inspect the actual importer.</strong> Open the <a href="https://github.com/kaw393939/is373-rag/blob/main/student-reference/rag_lab.py" target="_blank" rel="noreferrer">reference code</a>. Find the `paragraphs()` function, then inspect one <a href="https://github.com/kaw393939/is373-rag/blob/main/student-reference/fixtures/events.txt" target="_blank" rel="noreferrer">fictional source file</a>. Predict how many chunks it creates. Run the <a href="./reference#your-first-15-minutes">15-minute lab</a> and inspect real chunk text and `ordinal`.</p><p><strong>Experiment B — compare a proposed different split.</strong> In a copied test fixture, place a key sentence across an artificial 60-character boundary. Ask an AI coding agent to propose a fixed-character splitter and a paragraph splitter as <strong>separate experiments</strong>. Compare what each returns to <strong>“Who organizes workshops?”</strong> Keep the original fixture unchanged, save actual outputs and decide which split better preserves support.</p><p>Record <strong>the unit you counted</strong> (characters or tokens), tokenizer where relevant, source version, chunk count, retrieved IDs and question. If several hits repeat the same sentence, inspect overlap. If the answer is spread across two adjacent hits, try returning the parent section. Rerun the same question after one change.</p><h2 id="evaluate-the-result-before-changing-your-design" tabindex="-1">Evaluate the result before changing your design <a class="header-anchor" href="#evaluate-the-result-before-changing-your-design" aria-label="Permalink to &quot;Evaluate the result before changing your design&quot;">​</a></h2><p>For one supported, one paraphrased, and one unanswerable question, record:</p><ol><li><strong>Expected source/passage</strong> before execution.</li><li><strong>Retrieved chunk IDs and text</strong>, not just the model&#39;s explanation.</li><li>Whether the boundary preserved the entire fact or relationship.</li><li>Whether the actual answer&#39;s citations support each claim.</li><li>One change and a repeat run. Is retrieval better, worse or merely different?</li></ol><p>When a citation fails, investigate retrieval and source boundaries <strong>before</strong> asking the model to sound more certain.</p><h3 id="ask-an-ai-coding-partner" tabindex="-1">Ask an AI coding partner <a class="header-anchor" href="#ask-an-ai-coding-partner" aria-label="Permalink to &quot;Ask an AI coding partner&quot;">​</a></h3><p>```text Read my existing importer and my permitted source fixture. Show me its actual chunking rule; don&#39;t assume it uses tokens. Predict, then run the import and display source IDs, chunk IDs, text and source locations. Compare paragraph/heading boundaries with a second small strategy without replacing the first. Use the same three evaluation questions. Show any split claim, duplication or lost context, and record actual results. Do not install a framework or change my production import until I approve. Ask me which strategy I prefer and what evidence supports that choice. ```</p><h3 id="a-note-from-the-ai" tabindex="-1">A note from the AI <a class="header-anchor" href="#a-note-from-the-ai" aria-label="Permalink to &quot;A note from the AI&quot;">​</a></h3><blockquote><p>If my answer sounds too general, ask me to display the retrieved text beside the paragraph that follows it. You may find the exception one line beyond the cut.</p></blockquote><h2 id="more-to-explore" tabindex="-1">More to explore <a class="header-anchor" href="#more-to-explore" aria-label="Permalink to &quot;More to explore&quot;">​</a></h2><ul><li><a href="./embeddings">Embeddings handout</a>: numerical representations are computed <strong>after</strong> you select an input unit.</li><li><a href="./library-survey">AI library survey</a>: optional splitters and pipelines, including LangChain.</li><li><a href="https://github.com/kaw393939/is373-studio/blob/main/docs/handouts/database-rag-research.md" target="_blank" rel="noreferrer">Original IS373 RAG research handout</a>: assignment-aligned comparison.</li><li><a href="https://www.pinecone.io/learn/chunking-strategies/" target="_blank" rel="noreferrer">Pinecone chunking strategies</a>: practical tradeoffs and advanced methods.</li></ul><p><em>Fictional scenario and proposed experiments. No example claims a model was run or a benchmark was measured.</em></p>',20))])}const x=i(d,[["render",p]]);export{y as __pageData,x as default};
